begin;
create table public.proveedores(id_proveedor bigint generated by default as identity primary key,nombre varchar(150) not null,contacto varchar(150),email varchar(150),telefono varchar(30),direccion varchar(255),activo boolean not null default true);
alter table public.medicamentos add column id_proveedor bigint references public.proveedores;
create table public.eventos(id_evento bigint generated by default as identity primary key,id_sucursal bigint not null references public.sucursales,titulo varchar(150) not null,descripcion varchar(4000) not null,inicio timestamptz not null,fin timestamptz not null,foto_url text,publicado boolean not null default false,check(fin>inicio));
create table public.alertas_inventario(id_alerta bigint generated by default as identity primary key,clave text unique not null,tipo text not null check(tipo in ('VENCIDO','POR_VENCER','STOCK_BAJO')),id_sucursal bigint not null references public.sucursales,id_medicamento bigint not null references public.medicamentos,id_inventario bigint references public.inventario,mensaje text not null,estado text not null default 'ACTIVA',creado_en timestamptz not null default now(),enviado_en timestamptz);
do $$ declare t text;pk text;begin
 for t,pk in select * from(values('proveedores','id_proveedor'),('eventos','id_evento'),('alertas_inventario','id_alerta'))v(t,p) loop
 execute format('alter table public.%I enable row level security',t);execute format('grant select on public.%I to authenticated',t);execute format('grant all on public.%I to service_role',t);execute format('grant usage,select on sequence %s to service_role',pg_get_serial_sequence('public.'||t,pk));
 execute format('create policy lectura on public.%I for select to authenticated using(privado.permitido(array[''GERENTE'',''BODEGA'',''AUDITOR'']%s))',t,case when t='proveedores' then '' else ',id_sucursal' end);
 if t<>'alertas_inventario' then
 execute format('grant insert,update on public.%I to authenticated',t);execute format('grant usage,select on sequence %s to authenticated',pg_get_serial_sequence('public.'||t,pk));execute format('create policy editar on public.%I for all to authenticated using(privado.permitido(array[''ADMIN''])) with check(privado.permitido(array[''ADMIN'']))',t);
 execute format('create trigger historial after insert or update or delete on public.%I for each row execute function privado.auditar(%L)',t,pk);
 end if;end loop;end $$;
create function public.eventos_publicos(p_desde timestamptz,p_hasta timestamptz) returns jsonb language sql stable security definer set search_path=pg_catalog,public as $$
 select coalesce(jsonb_agg(jsonb_build_object('id',e.id_evento,'title',e.titulo,'start',e.inicio,'end',e.fin,'descripcion',e.descripcion,'foto_url',e.foto_url,'id_sucursal',s.id_sucursal,'sucursal',s.nombre,'direccion',s.direccion,'telefono',s.telefono) order by e.inicio),'[]'::jsonb)
 from public.eventos e join public.sucursales s using(id_sucursal) where e.publicado and s.estado='ACTIVA' and e.inicio<p_hasta and e.fin>p_desde;
$$;
revoke all on function public.eventos_publicos(timestamptz,timestamptz) from public;
grant execute on function public.eventos_publicos(timestamptz,timestamptz) to anon,authenticated;
create function public.generar_alertas_inventario() returns integer language plpgsql security definer set search_path=pg_catalog,public as $$
declare n integer;hoy date:=(now() at time zone 'America/Guatemala')::date;
begin
 perform pg_advisory_xact_lock(7062099);
 update public.alertas_inventario set estado='RESUELTA' where estado='ACTIVA';
 insert into public.alertas_inventario(clave,tipo,id_sucursal,id_medicamento,id_inventario,mensaje)
 select 'LOTE-'||i.id_inventario||'-'||hoy,case when i.fecha_vencimiento<=hoy then 'VENCIDO' else 'POR_VENCER' end,i.id_sucursal,i.id_medicamento,i.id_inventario,
 m.nombre||' · lote '||i.lote||' · vence '||i.fecha_vencimiento||' · unidades '||i.cantidad from public.inventario i join public.medicamentos m using(id_medicamento) where i.cantidad>0 and i.fecha_vencimiento<=hoy+30
 on conflict(clave) do update set estado='ACTIVA',tipo=excluded.tipo,mensaje=excluded.mensaje;
 insert into public.alertas_inventario(clave,tipo,id_sucursal,id_medicamento,mensaje)
 select 'STOCK-'||s.id_stock||'-'||hoy,'STOCK_BAJO',s.id_sucursal,s.id_medicamento,
 m.nombre||' · disponible '||coalesce(sum(i.cantidad-i.reservado) filter(where i.fecha_vencimiento>hoy),0)||' · mínimo '||s.stock_minimo
 from public.stock_minimos s join public.medicamentos m using(id_medicamento) left join public.inventario i on i.id_sucursal=s.id_sucursal and i.id_medicamento=s.id_medicamento group by s.id_stock,m.nombre having coalesce(sum(i.cantidad-i.reservado) filter(where i.fecha_vencimiento>hoy),0)<s.stock_minimo
 on conflict(clave) do update set estado='ACTIVA',mensaje=excluded.mensaje;
 select count(*) into n from public.alertas_inventario where estado='ACTIVA';return n;
end $$;
revoke all on function public.generar_alertas_inventario() from public,anon,authenticated;
grant execute on function public.generar_alertas_inventario() to service_role;
commit;
